-- Leads (M8): default stages, stage rules, row-level security and the enquiry form lookup.

-- Order keys are fractional-index strings and must compare byte by byte, whatever the
-- database's collation ("Zz" sorts before "a0").
ALTER TABLE pipeline_stages ALTER COLUMN position TYPE text COLLATE "C";--> statement-breakpoint
ALTER TABLE leads ALTER COLUMN position TYPE text COLLATE "C";--> statement-breakpoint

-- Every new workspace gets the default pipeline (defaults-and-content.md §2). Positions are
-- fractional-index keys, as generated by packages/core positions(5).
CREATE OR REPLACE FUNCTION public.seed_pipeline_stages() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO pipeline_stages (id, workspace_id, name, position, kind) VALUES
    (gen_random_uuid(), NEW.id, 'New', 'a0', 'open'),
    (gen_random_uuid(), NEW.id, 'Contacted', 'a1', 'open'),
    (gen_random_uuid(), NEW.id, 'Proposal', 'a2', 'open'),
    (gen_random_uuid(), NEW.id, 'Won', 'a3', 'won'),
    (gen_random_uuid(), NEW.id, 'Lost', 'a4', 'lost');
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER workspaces_seed_pipeline AFTER INSERT ON workspaces FOR EACH ROW EXECUTE FUNCTION seed_pipeline_stages();--> statement-breakpoint

-- Won and Lost are fixed: their kind can't change and they can't be deleted. Only open stages
-- are added.
CREATE OR REPLACE FUNCTION public.guard_pipeline_stage() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.kind <> 'open' THEN
    RAISE EXCEPTION 'stage_fixed';
  ELSIF TG_OP = 'UPDATE' AND NEW.kind <> OLD.kind THEN
    RAISE EXCEPTION 'stage_fixed';
  ELSIF TG_OP = 'DELETE' AND OLD.kind <> 'open' THEN
    RAISE EXCEPTION 'stage_fixed';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$$;--> statement-breakpoint
CREATE TRIGGER pipeline_stages_guard BEFORE INSERT OR UPDATE OR DELETE ON pipeline_stages
  FOR EACH ROW WHEN (pg_trigger_depth() = 0) EXECUTE FUNCTION guard_pipeline_stage();--> statement-breakpoint

-- A lead's stage is in its own workspace, and a lead in a Lost stage has a lost reason.
CREATE OR REPLACE FUNCTION public.check_lead_stage() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  stage_kind stage_kind;
BEGIN
  SELECT kind INTO stage_kind FROM pipeline_stages WHERE id = NEW.stage_id AND workspace_id = NEW.workspace_id;
  IF stage_kind IS NULL THEN
    RAISE EXCEPTION 'stage_not_found';
  END IF;
  IF stage_kind = 'lost' AND NEW.lost_reason IS NULL THEN
    RAISE EXCEPTION 'lost_reason_required';
  END IF;
  IF stage_kind = 'lost' AND NEW.lost_reason = 'other' AND coalesce(trim(NEW.lost_note), '') = '' THEN
    RAISE EXCEPTION 'lost_note_required';
  END IF;
  IF stage_kind <> 'lost' THEN
    NEW.lost_reason := NULL;
    NEW.lost_note := NULL;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER leads_check_stage BEFORE INSERT OR UPDATE OF stage_id, lost_reason, lost_note ON leads
  FOR EACH ROW EXECUTE FUNCTION check_lead_stage();--> statement-breakpoint

CREATE TRIGGER pipeline_stages_updated_at BEFORE UPDATE ON pipeline_stages FOR EACH ROW EXECUTE FUNCTION set_updated_at();--> statement-breakpoint
CREATE TRIGGER leads_updated_at BEFORE UPDATE ON leads FOR EACH ROW EXECUTE FUNCTION set_updated_at();--> statement-breakpoint
CREATE TRIGGER enquiry_forms_updated_at BEFORE UPDATE ON enquiry_forms FOR EACH ROW EXECUTE FUNCTION set_updated_at();--> statement-breakpoint

-- Can the signed-in user see the record an activity is about? Runs as the caller, so the
-- record's own policies decide. Later milestones add their subject types.
CREATE OR REPLACE FUNCTION public.activity_visible(p_workspace uuid, p_type text, p_id uuid) RETURNS boolean
LANGUAGE sql STABLE SET search_path = public AS $$
  SELECT CASE p_type
    WHEN 'lead' THEN EXISTS (SELECT 1 FROM leads WHERE id = p_id AND workspace_id = p_workspace)
    ELSE false
  END;
$$;--> statement-breakpoint

-- The workspace behind a public enquiry form link, for the public form page (anon may call it).
CREATE OR REPLACE FUNCTION public.enquiry_form_workspace(p_token_hash text) RETURNS uuid
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT workspace_id FROM enquiry_forms WHERE public_token_hash = p_token_hash AND is_active;
$$;--> statement-breakpoint

ALTER TABLE pipeline_stages ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE pipeline_stages FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE leads ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE leads FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE activities ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE activities FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE enquiry_forms ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE enquiry_forms FORCE ROW LEVEL SECURITY;--> statement-breakpoint

GRANT USAGE ON SCHEMA public TO anon;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON pipeline_stages, leads, enquiry_forms TO authenticated;--> statement-breakpoint
-- The timeline is append-only for members.
GRANT SELECT, INSERT ON activities TO authenticated;--> statement-breakpoint
GRANT ALL ON pipeline_stages, leads, activities, enquiry_forms TO service_role;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION activity_visible(uuid, text, uuid) TO authenticated, service_role;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION enquiry_form_workspace(text) TO anon, authenticated, service_role;--> statement-breakpoint

CREATE POLICY pipeline_stages_select ON pipeline_stages FOR SELECT TO authenticated
  USING (is_member(workspace_id));--> statement-breakpoint
CREATE POLICY pipeline_stages_insert ON pipeline_stages FOR INSERT TO authenticated
  WITH CHECK (has_permission(workspace_id, 'leads.write'));--> statement-breakpoint
CREATE POLICY pipeline_stages_update ON pipeline_stages FOR UPDATE TO authenticated
  USING (has_permission(workspace_id, 'leads.write'))
  WITH CHECK (has_permission(workspace_id, 'leads.write'));--> statement-breakpoint
CREATE POLICY pipeline_stages_delete ON pipeline_stages FOR DELETE TO authenticated
  USING (has_permission(workspace_id, 'leads.write'));--> statement-breakpoint

CREATE POLICY leads_select ON leads FOR SELECT TO authenticated
  USING (has_permission(workspace_id, 'leads.read'));--> statement-breakpoint
CREATE POLICY leads_insert ON leads FOR INSERT TO authenticated
  WITH CHECK (has_permission(workspace_id, 'leads.write'));--> statement-breakpoint
CREATE POLICY leads_update ON leads FOR UPDATE TO authenticated
  USING (has_permission(workspace_id, 'leads.write'))
  WITH CHECK (has_permission(workspace_id, 'leads.write'));--> statement-breakpoint
CREATE POLICY leads_delete ON leads FOR DELETE TO authenticated
  USING (has_permission(workspace_id, 'leads.delete'));--> statement-breakpoint

CREATE POLICY activities_select ON activities FOR SELECT TO authenticated
  USING (is_member(workspace_id) AND activity_visible(workspace_id, subject_type, subject_id));--> statement-breakpoint
CREATE POLICY activities_insert ON activities FOR INSERT TO authenticated
  WITH CHECK (actor_id = auth.uid() AND is_member(workspace_id) AND activity_visible(workspace_id, subject_type, subject_id));--> statement-breakpoint

CREATE POLICY enquiry_forms_select ON enquiry_forms FOR SELECT TO authenticated
  USING (has_permission(workspace_id, 'leads.read'));--> statement-breakpoint
CREATE POLICY enquiry_forms_write ON enquiry_forms FOR ALL TO authenticated
  USING (has_permission(workspace_id, 'leads.write'))
  WITH CHECK (has_permission(workspace_id, 'leads.write'));
